CREATE PROCEDURE [Premi_selectchanges]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int,
	@sync_update_peer_key Int
AS
BEGIN
SELECT [side].[Codice], [base].[Descrizione], [base].[Costo], [base].[N_Tickets], [base].[Fornitore], [base].[Quantita], [base].[Riserva], [base].[CodOr], [base].[Foto], [base].[QPren], [base].[Id], [base].[Ordinato], [base].[Conf], [base].[QDis1], [base].[PDis1], [base].[QDis2], [base].[PDis2], [base].[QDis3], [base].[PDis3], [base].[QDis4], [base].[PDis4], [base].[QDis5], [base].[PDis5], [base].[QDis6], [base].[PDis6], [base].[QDis7], [base].[PDis7], [base].[QDis8], [base].[PDis8], [base].[Attivo], [base].[Gru], [base].[Riord], [base].[Locked], [base].[Id2], [base].[Icona], [base].[Prenotabile], [base].[NImp], [base].[F0], [base].[T0], [base].[N0], [base].[D0], [base].[F1], [base].[T1], [base].[N1], [base].[D1], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key FROM [Premi] [base] RIGHT JOIN [Premi_tracking] [side] ON [base].[Codice] = [side].[Codice] WHERE  ([side].[update_scope_local_id] IS NULL OR [side].[update_scope_local_id] <> @sync_scope_local_id OR ([side].[update_scope_local_id] = @sync_scope_local_id AND [side].[scope_update_peer_key] <> @sync_update_peer_key)) AND [side].[local_update_peer_timestamp] > @sync_min_timestamp
END
